    private static OrderInternalDto CreateDto(
        Guid? id = null,
        DateTime? updatedAtUtc = null)
    {
        var updated = updatedAtUtc ?? DateTime.UtcNow;
        return new OrderInternalDto
        {
            Id = id ?? Guid.NewGuid(),
            CreatedAtUtc = updated.AddDays(-1),
            UpdatedAtUtc = updated,
            CustomerId = Guid.NewGuid(),
            Status = "Pending",
            TotalAmount = 10.00m,
            TotalPrice = null
        };
    }

    private static OrderEntity CreateEntity(
        Guid? id = null,
        DateTime? updatedAtUtc = null)
    {
        var dto = CreateDto(id, updatedAtUtc);
        return new OrderEntity
        {
            Id = dto.Id,
            CreatedAtUtc = dto.CreatedAtUtc,
            UpdatedAtUtc = dto.UpdatedAtUtc,
            CustomerId = dto.CustomerId,
            Status = dto.Status,
            TotalAmount = dto.TotalAmount,
            TotalPrice = dto.TotalPrice
        };
    }

    private static OrderServiceSearchRequest CreateSearchRequest(
